"""实际ProcessPacket/Send与内核链路；Socket与Unity接口为离线替身。"""
import json
from pathlib import Path
import pytest
from tools.gm_console.runtime_gm_code import read_runtime_gm_source
ROOT=Path(__file__).parents[1]/'tools/gm_console'
def test_bt_json_real_packet_path():
    lua=pytest.importorskip('lupa').LuaRuntime(unpack_returned_tuples=True)
    source=read_runtime_gm_source()
    modules=source.split('-- 2. RuntimeGMClient')[0]
    legacy='--\n-- json.lua\n--\n-- Copyright (c) 2019 rxi\n--\n-- Permission is hereby granted, free of charge, to any person obtaining a copy of\n-- this software and associated documentation files (the "Software"), to deal in\n-- the Software without restriction, including without limitation the rights to\n-- use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies\n-- of the Software, and to permit persons to whom the Software is furnished to do\n-- so, subject to the following conditions:\n--\n-- The above copyright notice and this permission notice shall be included in all\n-- copies or substantial portions of the Software.\n--\n-- THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\n-- IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\n-- FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\n-- AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\n-- LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\n-- OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\n-- SOFTWARE.\n--\nlocal json = { _version = "0.1.2" }\n\n-------------------------------------------------------------------------------\n-- Encode\n-------------------------------------------------------------------------------\nlocal encode\n\nlocal escape_char_map = {\n    ["\\\\"] = "\\\\\\\\",\n    ["\\""] = "\\\\\\"",\n    ["\\b"] = "\\\\b",\n    ["\\f"] = "\\\\f",\n    ["\\n"] = "\\\\n",\n    ["\\r"] = "\\\\r",\n    ["\\t"] = "\\\\t",\n}\n\nlocal escape_char_map_inv = {["\\\\/"] = "/" }\nfor k, v in pairs(escape_char_map) do\n    escape_char_map_inv[v] = k\nend\n\n\nlocal function escape_char(c)\n    return escape_char_map[c] or string.format("\\\\u%04x", c:byte())\nend\n\n\nlocal function encode_nil()\n    return "null"\nend\n\n\nlocal function encode_table(val, stack)\n    local res = {}\n    stack = stack or {}\n\n    -- Circular reference?\n    if stack[val] then error("circular reference") end\n\n    stack[val] = true\n\n    if rawget(val, 1) ~= nil or next(val) == nil then\n        -- Treat as array -- check keys are valid and it is not sparse\n        local n = 0\n        for k in pairs(val) do\n            if type(k) ~= "number" then\n                error("invalid table: mixed or invalid key types")\n            end\n            n = n + 1\n        end\n        if n ~= #val then\n            error("invalid table: sparse array")\n        end\n        -- Encode\n        for _, v in ipairs(val) do\n            table.insert(res, encode(v, stack))\n        end\n        stack[val] = nil\n        return "[" .. table.concat(res, ",") .. "]"\n\n    else\n        -- Treat as an object\n        for k, v in pairs(val) do\n            if type(k) ~= "string" then\n                error("invalid table: mixed or invalid key types")\n            end\n            table.insert(res, encode(k, stack) .. ":" .. encode(v, stack))\n        end\n        stack[val] = nil\n        return "{" .. table.concat(res, ",") .. "}"\n    end\nend\n\n\nlocal function encode_string(val)\n    return \'"\' .. val:gsub(\'[%z\\1-\\31\\\\"]\', escape_char) .. \'"\'\nend\n\n\nlocal function encode_number(val)\n    -- Check for NaN, -inf and inf\n    if val ~= val or val <= -math.huge or val >= math.huge then\n        error("unexpected number value \'" .. tostring(val) .. "\'")\n    end\n    return string.format("%.14g", val)\nend\n\n\nlocal type_func_map = {\n    ["nil"    ] = encode_nil,\n    ["table"] = encode_table,\n    ["string"] = encode_string,\n    ["number"] = encode_number,\n    ["boolean"] = tostring,\n}\n\n\nencode = function(val, stack)\n    local t = type(val)\n    local f = type_func_map[t]\n    if f then\n        return f(val, stack)\n    end\n    error("unexpected type \'" .. t .. "\'")\nend\n\n\nfunction json.encode(val)\n    return (encode(val))\nend\n\n\n-------------------------------------------------------------------------------\n-- Decode\n-------------------------------------------------------------------------------\nlocal parse\n\nlocal function create_set(...)\n    local res = {}\n    for i = 1, select("#", ...) do\n        res[select(i, ...)] = true\n    end\n    return res\nend\n\nlocal space_chars = create_set(" ", "\\t", "\\r", "\\n")\nlocal delim_chars = create_set(" ", "\\t", "\\r", "\\n", "]", "}", ",")\nlocal escape_chars = create_set("\\\\", "/", \'"\', "b", "f", "n", "r", "t", "u")\nlocal literals    = create_set("true", "false", "null")\n\nlocal literal_map = {\n    ["true"] = true,\n    ["false"] = false,\n    ["null"] = nil,\n}\n\n\nlocal function next_char(str, idx, set, negate)\n    for i = idx, #str do\n        if set[str:sub(i, i)] ~= negate then\n            return i\n        end\n    end\n    return #str + 1\nend\n\n\nlocal function decode_error(str, idx, msg)\n    local line_count = 1\n    local col_count = 1\n    for i = 1, idx - 1 do\n        col_count = col_count + 1\n        if str:sub(i, i) == "\\n" then\n            line_count = line_count + 1\n            col_count = 1\n        end\n    end\n    error(string.format("%s at line %d col %d", msg, line_count, col_count))\nend\n\n\nlocal function codepoint_to_utf8(n)\n    -- http://scripts.sil.org/cms/scripts/page.php?site_id=nrsi&id=iws-appendixa\n    local f = math.floor\n    if n <= 0x7f then\n        return string.char(n)\n    elseif n <= 0x7ff then\n        return string.char(f(n / 64) + 192, n % 64 + 128)\n    elseif n <= 0xffff then\n        return string.char(f(n / 4096) + 224, f(n % 4096 / 64) + 128, n % 64 + 128)\n    elseif n <= 0x10ffff then\n        return string.char(f(n / 262144) + 240, f(n % 262144 / 4096) + 128,\n        f(n % 4096 / 64) + 128, n % 64 + 128)\n    end\n    error(string.format("invalid unicode codepoint \'%x\'", n))\nend\n\n\nlocal function parse_unicode_escape(s)\n    local n1 = tonumber(s:sub(3, 6), 16)\n    local n2 = tonumber(s:sub(9, 12), 16)\n    -- Surrogate pair?\n    if n2 then\n        return codepoint_to_utf8((n1 - 0xd800) * 0x400 + (n2 - 0xdc00) + 0x10000)\n    else\n        return codepoint_to_utf8(n1)\n    end\nend\n\n\nlocal function parse_string(str, i)\n    local has_unicode_escape = false\n    local has_surrogate_escape = false\n    local has_escape = false\n    local last\n    for j = i + 1, #str do\n        local x = str:byte(j)\n\n        if x < 32 then\n            decode_error(str, j, "control character in string")\n        end\n\n        if last == 92 then -- "\\\\" (escape char)\n            if x == 117 then -- "u" (unicode escape sequence)\n                local hex = str:sub(j + 1, j + 5)\n                if not hex:find("%x%x%x%x") then\n                    decode_error(str, j, "invalid unicode escape in string")\n                end\n                if hex:find("^[dD][89aAbB]") then\n                    has_surrogate_escape = true\n                else\n                    has_unicode_escape = true\n                end\n            else\n                local c = string.char(x)\n                if not escape_chars[c] then\n                    decode_error(str, j, "invalid escape char \'" .. c .. "\' in string")\n                end\n                has_escape = true\n            end\n            last = nil\n\n        elseif x == 34 then -- \'"\' (end of string)\n            local s = str:sub(i + 1, j - 1)\n            if has_surrogate_escape then\n                s = s:gsub("\\\\u[dD][89aAbB]..\\\\u....", parse_unicode_escape)\n            end\n            if has_unicode_escape then\n                s = s:gsub("\\\\u....", parse_unicode_escape)\n            end\n            if has_escape then\n                s = s:gsub("\\\\.", escape_char_map_inv)\n            end\n            return s, j + 1\n\n        else\n            last = x\n        end\n    end\n    decode_error(str, i, "expected closing quote for string")\nend\n\n\nlocal function parse_number(str, i)\n    local x = next_char(str, i, delim_chars)\n    local s = str:sub(i, x - 1)\n    local n = tonumber(s)\n    if not n then\n        decode_error(str, i, "invalid number \'" .. s .. "\'")\n    end\n    return n, x\nend\n\n\nlocal function parse_literal(str, i)\n    local x = next_char(str, i, delim_chars)\n    local word = str:sub(i, x - 1)\n    if not literals[word] then\n        decode_error(str, i, "invalid literal \'" .. word .. "\'")\n    end\n    return literal_map[word], x\nend\n\n\nlocal function parse_array(str, i)\n    local res = {}\n    local n = 1\n    i = i + 1\n    while 1 do\n        local x\n        i = next_char(str, i, space_chars, true)\n        -- Empty / end of array?\n        if str:sub(i, i) == "]" then\n            i = i + 1\n            break\n        end\n        -- Read token\n        x, i = parse(str, i)\n        res[n] = x\n        n = n + 1\n        -- Next token\n        i = next_char(str, i, space_chars, true)\n        local chr = str:sub(i, i)\n        i = i + 1\n        if chr == "]" then break end\n        if chr ~= "," then decode_error(str, i, "expected \']\' or \',\'") end\n    end\n    return res, i\nend\n\n\nlocal function parse_object(str, i)\n    local res = {}\n    i = i + 1\n    while 1 do\n        local key, val\n        i = next_char(str, i, space_chars, true)\n        -- Empty / end of object?\n        if str:sub(i, i) == "}" then\n            i = i + 1\n            break\n        end\n        -- Read key\n        if str:sub(i, i) ~= \'"\' then\n            decode_error(str, i, "expected string for key")\n        end\n        key, i = parse(str, i)\n        -- Read \':\' delimiter\n        i = next_char(str, i, space_chars, true)\n        if str:sub(i, i) ~= ":" then\n            decode_error(str, i, "expected \':\' after key")\n        end\n        i = next_char(str, i + 1, space_chars, true)\n        -- Read value\n        val, i = parse(str, i)\n        -- Set\n        res[key] = val\n        -- Next token\n        i = next_char(str, i, space_chars, true)\n        local chr = str:sub(i, i)\n        i = i + 1\n        if chr == "}" then break end\n        if chr ~= "," then decode_error(str, i, "expected \'}\' or \',\'") end\n    end\n    return res, i\nend\n\n\nlocal char_func_map = {\n    [\'"\'] = parse_string,\n    ["0"] = parse_number,\n    ["1"] = parse_number,\n    ["2"] = parse_number,\n    ["3"] = parse_number,\n    ["4"] = parse_number,\n    ["5"] = parse_number,\n    ["6"] = parse_number,\n    ["7"] = parse_number,\n    ["8"] = parse_number,\n    ["9"] = parse_number,\n    ["-"] = parse_number,\n    ["t"] = parse_literal,\n    ["f"] = parse_literal,\n    ["n"] = parse_literal,\n    ["["] = parse_array,\n    ["{"] = parse_object,\n}\n\n\nparse = function(str, idx)\n    local chr = str:sub(idx, idx)\n    local f = char_func_map[chr]\n    if f then\n        return f(str, idx)\n    end\n    decode_error(str, idx, "unexpected character \'" .. chr .. "\'")\nend\n\n\nfunction json.decode(str)\n    if type(str) ~= "string" then\n        error("expected argument of type string, got " .. type(str))\n    end\n    local res, idx = parse(str, next_char(str, 1, space_chars, true))\n    idx = next_char(str, idx, space_chars, true)\n    if idx <= #str then\n        decode_error(str, idx, "trailing garbage")\n    end\n    return res\nend\n\n\nreturn json\n'
    received=[]
    lua.globals().capture=lambda text:received.append(json.loads(text))
    send=source[source.index('    function RuntimeGMClient.Send(data, timeout)'):source.index('    function RuntimeGMClient.SendLog')]
    process=source[source.index('    function RuntimeGMClient.ProcessPacket(line)'):source.index('    function RuntimeGMClient.Start(host, port)')]
    harness="""
local legacy=(function() LEGACYSRC end)()
package.preload['XCommon/Json']=function()return legacy end
local jsonEncode=legacy.encode
local jsonDecode=legacy.decode
local origin_print=function()end
RuntimeGMClient={Socket={settimeout=function()end,send=function(_,text) capture(text);return #text end}}
""".replace('LEGACYSRC',legacy)
    setup="""
local host={now=function()return 0 end,scene=function()return 'test' end,send=RuntimeGMClient.Send}
BTHandlersTest=BehaviorTreeHandlers
RuntimeGMClient.BehaviorTree=CreateBehaviorTree(host,BehaviorTreeDefinitions,BehaviorTreeHandlers)
"""
    lua.execute(modules+harness+send+process+setup)
    probe={'serialization_probe':{'nil_value':None,'empty_array':[],'empty_object':{},'nested':[1,False,{'value':None}],'null_array':[None,None],'unicode':'中文\n😀'}}
    tree={'schemaVersion':1,'id':'json','root':'root','nodes':[{'id':'root','type':'wait','version':1,'params':{'seconds':0},'children':[]}],'roles':{},'blackboard':probe}
    def request(ident,action,payload):
        lua.globals().RuntimeGMClient.ProcessPacket(json.dumps({'protocolVersion':1,'type':'BT_REQUEST','requestId':ident,'action':action,'payload':payload},ensure_ascii=True))
        return received[-1]
    assert request('install','install',{'tree':tree})['data']['ok']
    assert request('start','start',{'treeId':'json','bindings':{}})['data']['blackboard']==probe
    lua.globals().RuntimeGMClient.BehaviorTree.update()
    assert request('status','status',{})['data']['runs'][0]['blackboard']==probe
    assert request('start2','start',{'treeId':'json','bindings':{}})['data']['blackboard']==probe
    request('stop2','stop',{})
    # 参数null与节点写入同样保真；空数组和空对象不能等值。
    for i,value in enumerate([None,[],{},[None,False,{'n':None}],1.2345678901234567]):
        tree['id']='write'+str(i)
        tree['nodes']=[{'id':'root','type':'sequence','version':1,'params':{},'children':['set','eq']},
                       {'id':'set','type':'blackboard_set','version':1,'params':{'key':'x','value':value},'children':[]},
                       {'id':'eq','type':'blackboard_equals','version':1,'params':{'key':'x','value':value},'children':[]}]
        assert request('i'+str(i),'install',{'tree':tree})['data']['ok']
        request('r'+str(i),'start',{'treeId':tree['id'],'bindings':{}})
        lua.globals().RuntimeGMClient.BehaviorTree.update()
        run=next(r for r in request('s'+str(i),'status',{})['data']['runs'] if r['treeId']==tree['id'])
        assert run['state']=='succeeded' and run['blackboard']['x']==value
    tree['blackboard']=None
    assert not request('null-bb','validate',{'tree':tree})['data']['ok']
    # 非BT仍走原编码，未改变其历史空表语义。
    lua.execute("RuntimeGMClient.Send({type='LEGACY',data={}})")
    assert received[-1]=={'type':'LEGACY','data':[]}
    # ByRef属性访问设为错误，只允许实际替代接口。
    lua.execute("""
CS={System={Convert={ToInt32=function(value)return value end}},XNpcAttribType={Life=1,Energy=2}}
local npc=setmetatable({Id=1,IsDeleted=false,IsDead=false,Attrib={[1]={Value=123},[2]={Value=45}},Position='p',CurrentAction='a'}, {__index=function(_,key)if key=='Life' or key=='Energy' then error('ByRef reflection prohibited')end end})
local result
assert(BTHandlersTest.fight_read({params={role='player',output='state'},object=function()return {Frame=1,GetClientRole=function()return {Npc=npc}end}end,write=function(_,value)result=value end})=='succeeded')
assert(result.life==123 and result.energy==45)
""")
